const KEY='campusly-registered';const page=document.body.dataset.page;const getRegs=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch{return []}};const saveRegs=x=>localStorage.setItem(KEY,JSON.stringify(x));const registered=()=>getRegs().map(id=>courses.find(c=>c.id===id)).filter(Boolean);const el=(s)=>document.querySelector(s);const app=el('#app');
function shell(content){app.innerHTML=`<header><nav class="nav"><a class="brand" href="index.html"><span class="brand-mark">✦</span>campusly</a><button class="menu-toggle" aria-label="Toggle navigation" aria-expanded="false">☰</button><div class="nav-links">${links.map(([key,url,label])=>`<a href="${url}" class="${key===page?'active':''} ${key==='registration'?'nav-cta':''}">${label}</a>`).join('')}</div></nav></header><main class="container">${content}</main><footer class="footer"><div class="container"><span>© 2025 Campusly University</span><span>Learn something wonderful.</span></div></footer>`;const toggle=el('.menu-toggle');toggle.addEventListener('click',()=>{const open=el('.nav-links').classList.toggle('open');toggle.setAttribute('aria-expanded',String(open))})}
function card(c,action='Add course'){const isIn=getRegs().includes(c.id);return `<article class="course-card"><div class="card-top"><span class="course-icon ${c.color}">${c.icon}</span><span class="badge">${c.category}</span></div><div class="course-code">${c.id} · ${c.credits} credits</div><h3>${c.name}</h3><p>${c.description}</p><div class="course-meta"><span>◷ ${c.time}</span><span>♙ ${c.seats} seats</span></div><div class="card-action"><span class="course-code">${c.instructor}</span>${action==='Browse'?`<a class="text-link" href="catalog.html">Explore →</a>`:`<button class="${isIn?'secondary':''} course-action" data-id="${c.id}" ${isIn?'disabled':''}>${isIn?'Added ✓':'＋ Add'}</button>`}</div></article>`}
function bindAdd(){document.querySelectorAll('.course-action').forEach(b=>b.addEventListener('click',()=>{const ids=getRegs();if(!ids.includes(b.dataset.id)){ids.push(b.dataset.id);saveRegs(ids);b.textContent='Added ✓';b.classList.add('secondary');b.disabled=true;updateCounts()}}))}function updateCounts(){document.querySelectorAll('[data-count]').forEach(x=>x.textContent=registered().length)}
function catalog(){shell(`<div class="page-heading"><h1>Course catalog</h1><p>Find a class that fits your interests and your schedule.</p></div><section class="filter-panel"><div class="field"><label for="search">Search courses</label><div class="input-wrap"><span>⌕</span><input id="search" placeholder="Course name, code, or instructor" type="search"></div></div><div class="field"><label for="department">Department</label><select id="department"><option value="">All departments</option>${[...new Set(courses.map(c=>c.department))].sort().map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label for="category">Subject area</label><select id="category"><option value="">All subject areas</option>${[...new Set(courses.map(c=>c.category))].sort().map(x=>`<option>${x}</option>`).join('')}</select></div><button id="clear" class="secondary">Clear filters</button></section><div class="results-line"><span id="result-count"></span><span>Fall semester · 2025</span></div><section id="catalog-grid" class="course-grid"></section>`);const search=el('#search'),dept=el('#department'),cat=el('#category');function render(){const term=search.value.trim().toLowerCase();const list=courses.filter(c=>(!term||`${c.name} ${c.id} ${c.instructor} ${c.description}`.toLowerCase().includes(term))&&(!dept.value||c.department===dept.value)&&(!cat.value||c.category===cat.value));el('#result-count').textContent=`Showing ${list.length} of ${courses.length} courses`;el('#catalog-grid').innerHTML=list.length?list.map(c=>card(c)).join(''):`<div class="empty-state">No courses match those filters. Try another search.</div>`;bindAdd()}[search,dept,cat].forEach(x=>x.addEventListener('input',render));el('#clear').addEventListener('click',()=>{search.value='';dept.value='';cat.value='';render()});render()}
function tableRows(list,remove=false){return list.map(c=>`<tr><td><span class="table-course">${c.name}</span><span class="table-sub">${c.id} · ${c.department}</span></td><td>${c.instructor}</td><td>${c.time}</td><td><span class="credits">${c.credits}</span></td>${remove?`<td><button class="ghost remove-course" data-id="${c.id}" aria-label="Remove ${c.name}">Remove</button></td>`:''}</tr>`).join('')}
function modal(){return `<div class="modal-backdrop" id="confirm-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal"><div class="modal-icon">✓</div><h2 id="modal-title">You're all set!</h2><p id="modal-copy"></p><div class="modal-actions"><button class="secondary" id="modal-edit">Keep exploring</button><button id="modal-done">View my schedule</button></div></div></div>`}
function registration(){let list=registered();shell(`<div class="page-heading"><h1>Course registration</h1><p>Choose classes for your Fall 2025 semester.</p></div><div class="content-layout"><aside class="side-card"><h3>Student details</h3><p>Confirm your information before registering.</p><form id="reg-form"><div class="field"><label for="student-name">Full name</label><input id="student-name" name="name" value="Jordan Lee" required></div><div class="field"><label for="student-id">Student ID</label><input id="student-id" name="studentId" value="U20250184" required></div><div class="field"><label for="student-email">University email</label><input id="student-email" name="email" type="email" value="jordan.lee@campus.edu" required></div><div class="notice">You can register for up to 18 credits per semester. Your schedule currently has <strong data-credit-count>${list.reduce((n,c)=>n+c.credits,0)}</strong> credits.</div><button type="submit" style="width:100%">Confirm registration →</button></form></aside><section><div class="panel"><div class="panel-header"><div><h2>Your selected courses</h2><p>Review your choices before confirming.</p></div><span class="badge"><span data-count>${list.length}</span> selected</span></div><div id="reg-table" class="table-wrap"></div><div class="actions"><a class="button secondary" href="catalog.html">＋ Add courses</a><button id="submit-reg" ${list.length?'':'disabled'}>Register for courses →</button></div></div><div class="panel"><h2>Registration tip</h2><p class="helper">Check course meeting times before confirming. This demo keeps your selected courses on this device.</p></div></section></div>${modal()}`);function render(){list=registered();el('#reg-table').innerHTML=list.length?`<table><thead><tr><th>Course</th><th>Instructor</th><th>Meeting time</th><th>Credits</th><th></th></tr></thead><tbody>${tableRows(list,true)}</tbody></table>`:`<div class="empty-state">Your schedule is ready for something. Add a course from the catalog to get started.</div>`;el('#submit-reg').disabled=!list.length;el('[data-count]').textContent=list.length;el('[data-credit-count]').textContent=list.reduce((n,c)=>n+c.credits,0);document.querySelectorAll('.remove-course').forEach(b=>b.addEventListener('click',()=>{saveRegs(getRegs().filter(x=>x!==b.dataset.id));render()}))}render();const showModal=()=>{el('#modal-copy').textContent=`${list.length} ${list.length===1?'course':'courses'} totaling ${list.reduce((n,c)=>n+c.credits,0)} credits have been added to your Fall 2025 schedule.`;el('#confirm-modal').classList.add('open')};el('#submit-reg').addEventListener('click',showModal);el('#reg-form').addEventListener('submit',e=>{e.preventDefault();showModal()});el('#modal-edit').addEventListener('click',()=>el('#confirm-modal').classList.remove('open'));el('#modal-done').addEventListener('click',()=>location.href='profile.html');el('#confirm-modal').addEventListener('click',e=>{if(e.target.id==='confirm-modal')e.currentTarget.classList.remove('open')})}
